#!/usr/bin/env python3
from pathlib import Path
import re, subprocess, sys, base64

ROOT=Path.cwd()
if not (ROOT/"athletics-portal").exists():
    raise SystemExit("Run from the Explore-Academy repository root.")

def dec(x): return base64.b64decode(x).decode()
def reqrep(text, old, new, label):
    if old not in text:
        raise SystemExit(f"Expected {label} not found. Stop rather than guess.")
    return text.replace(old,new,1)

portal=ROOT/"athletics-portal/js/portal.js"
areg=ROOT/"athletics-portal/js/admin-registrations.js"
aath=ROOT/"athletics-portal/js/admin-athletes.js"
acomp=ROOT/"athletics-portal/js/admin-compliance.js"
phtml=ROOT/"athletics-portal/portal.html"
ahtml=ROOT/"athletics-portal/admin.html"

# Family portal
s=portal.read_text()
helper=dec("")
s=reqrep(s,'let teams=fallbackTeams, athletes=[], athlete=null, registrations=[], payments=[], documents=[];\n',
         'let teams=fallbackTeams, athletes=[], athlete=null, registrations=[], payments=[], documents=[];\n'+helper+'\n',"portal state")
s=reqrep(s,'await Promise.all([loadRegistrations(),loadPayments(),loadDocuments()]);',
         'await loadRegistrations();\n await Promise.all([loadPayments(),loadDocuments()]);',"portal load order")
s=s.replace('await loadRegistrations();renderPathway();\n flash("registrationStatus"',
            'await loadRegistrations();renderPathway();await loadDocuments();\n flash("registrationStatus"',1)
s=s.replace('await loadRegistrations();renderPathway();\n}\nasync function loadRegistrations()',
            'await loadRegistrations();renderPathway();await loadDocuments();\n}\nasync function loadRegistrations()',1)
start=s.index("async function loadDocuments(){")
end=s.index("\nconst SQUARE_FUNCTION_URL=",start)
s=s[:start]+dec("")+s[end:]
s=s.replace('n==="insurance"?"Proof of Insurance":','n==="insurance"?"Proof of Insurance (legacy / not required)":')
portal.write_text(s)

# Admin compliance
acomp.write_text(dec(""))

# Registrations
s=areg.read_text()
s=reqrep(s,dec(""),dec(""),"registration clearance policy")
s=s.replace('${docs.approved}/6 ${docs.approved===6?','${docs.approved}/${docs.required} ${docs.approved===docs.required?')
s=s.replace('if(docs.approved<2){','if(docs.approved<docs.required){')
s=s.replace('${docs.approved}/6 required documents approved','${docs.approved}/${docs.required} required clearance items approved')
areg.write_text(s)

# Athletes
s=aath.read_text()
s=reqrep(s,'let athletes = [];\nlet detailCache','let athletes = [];\nlet teams = [];\nlet detailCache',"athlete state")
s=reqrep(s,dec(""),dec(""),"athlete clearance policy")
s=reqrep(s,'const snap=await getDocs(collection(db,"athletes"));\n    athletes=snap.docs.map',
         'const [snap,teamSnap]=await Promise.all([getDocs(collection(db,"athletes")),getDocs(collection(db,"teams"))]);\n    teams=teamSnap.docs.map(d=>({id:d.id,...d.data()}));\n    athletes=snap.docs.map',"athlete/team load")
s=s.replace('complianceSummary(d.documents)','complianceSummary(d.documents,d.registrations)')
s=s.replace('${comp.approved}/6','${comp.approved}/${comp.required}')
s=reqrep(s,dec("ZnVuY3Rpb24gZG9jTGFiZWwodil7CiAgcmV0dXJuIHY9PT0iYmlydGgtY2VydGlmaWNhdGUiPyJCaXJ0aCBDZXJ0aWZpY2F0ZSI6dj09PSJwaHlzaWNhbCI/IlNwb3J0cyBQaHlzaWNhbCI6dj09PSJpbnN1cmFuY2UiPyJJbnN1cmFuY2UiOiJEb2N1bWVudCI7Cn0="),dec(""),"document labels")
aath.write_text(s)

# HTML cleanup
s=phtml.read_text()
s=s.replace('id="docMetric" class="metric">0/6<','id="docMetric" class="metric">0/4<')
s=s.replace('All six Explore Academy athletics requirements must be approved before an athlete is cleared for practices and competitions.',
            'All athletes need four Explore Academy clearance items. CAA athletes also need the NFHS concussion certificate.')
s=re.sub(r'\s*<option value="insurance">Proof of Insurance</option>','',s)
phtml.write_text(s)

s=ahtml.read_text()
s=s.replace('Six required Explore Academy items. All six must be approved before practices or competitions unless an admin override is recorded.',
            'Four Explore Academy clearance items are required for every athlete. CAA athletes also require the NFHS concussion certificate.')
s=s.replace('<th>Conduct</th><th>Insurance</th><th>Clearance</th>','<th>Conduct</th><th>Clearance</th>')
s=re.sub(r'<option value="insurance">Proof of Insurance</option>','',s)
s=s.replace('<section id="paymentsPanel"<section id="paymentsPanel"','<section id="paymentsPanel"')
ahtml.write_text(s)

# Syntax validation
for f in [portal,acomp,aath,areg]:
    r=subprocess.run(["node","--check",str(f)],capture_output=True,text=True)
    if r.returncode:
        print(r.stderr)
        raise SystemExit(f"Syntax check failed: {f}")

print("✓ Non-CAA clearance = 4/4")
print("✓ CAA clearance = 5/5")
print("✓ Physical + questionnaire required for both")
print("✓ NFHS concussion certificate only for CAA")
print("✓ Insurance removed from active requirements")
print("✓ Family uploads supported")
print("✓ Admin counters/roster badges updated")
print("✓ JavaScript syntax checks passed")

if "--push" in sys.argv:
    subprocess.run(["git","add","athletics-portal"],check=True)
    if subprocess.run(["git","diff","--cached","--quiet"]).returncode:
        subprocess.run(["git","commit","-m","Make athletics clearance dynamic by league"],check=True)
        subprocess.run(["git","pull","--rebase","origin","main"],check=True)
        subprocess.run(["git","push","origin","main"],check=True)
        print("✓ Pushed to GitHub main")
    else:
        print("Nothing new to commit.")
